// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Keep the fuzzed amount in a realistic positive range for a payable deposit.
        amount = bound(amount, 1, type(uint96).max);

        // Adversarial counterparty: a caller whose receive() rejects Ether.
        ReverterCaller attacker = new ReverterCaller(address(c));
        vm.deal(address(attacker), amount);

        // Fund the attacker's C balance through the public addToBalance() entry point.
        attacker.deposit{value: amount}();

        // The attacker attempts to withdraw; the correct C must revert because
        // the Ether transfer to the rejecting caller fails.
        bool ok = attacker.withdraw();

        // P must revert (ok == false) and preserve the nonzero balance;
        // M does not revert (ok == true) and zeroes the balance.
        assertTrue(ok == false && c.getBalance(address(attacker)) == amount);
    }
}

contract ReverterCaller {
    Reentrance private immutable c;

    constructor(address _c) {
        c = Reentrance(_c);
    }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    function withdraw() external returns (bool) {
        try c.withdrawBalance() {
            return true;
        } catch {
            return false;
        }
    }

    receive() external payable {
        revert();
    }
}
